@Test
    public void testMutableClasses() throws Exception
    {
        assertTrue(CloneHelper.needsCloning(new MutableClass()));
        assertFalse(CloneHelper.needsCloning(ImmutableEnum.TEST));
        assertFalse(CloneHelper.needsCloning(null));
    }

